const nf=(n,d=1)=>new Intl.NumberFormat('sv-SE',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const integer=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:0}).format(n);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function estimateHomes(pupils,childrenPerFamily,share){if(childrenPerFamily<=0||share<=0)return 0;return Math.ceil(pupils/childrenPerFamily/(share/100));}
function effectYears(period,ramp){return ramp===0?period:period<=ramp?period*period/(2*ramp):period-ramp/2;}
function calculate(s){
 const local=areas.map(a=>({...a,homes:s['homes_'+a.key],price:s['price_'+a.key],loss:s['homes_'+a.key]*s['price_'+a.key]*s.drop/100}));
 const homes=local.reduce((t,a)=>t+a.homes,0),housing=local.reduce((t,a)=>t+a.loss,0);
 const km=s.drivingHouseholds*s.kmPerDay*s.drivingDays;
 const fuel=km/10*s.litersPerMil*s.fuelPrice;
 const otherCar=km*s.otherCostPerKm;
 const driving=fuel+otherCar;
 const adultHours=s.drivingHouseholds*s.adultMinutes*s.drivingDays/60;
 const pupilHours=252*s.pupilMinutes*2*s.schoolDays/60;
 const perHouseholdTax=s.taxpayers*s.taxableIncome*s.taxRate/100;
 const netDepartures=s.departures-s.newHouseholds;
 const grossTax=netDepartures*perHouseholdTax;
 const cumulativeTax=grossTax*effectYears(s.years,s.ramp);
 const cumulativeDriving=driving*s.years;
 const commuters=local.map(a=>({...a,families:Math.ceil(a.pupils/s.childPerHousehold),commuters:Math.round(Math.ceil(a.pupils/s.childPerHousehold)*s['commuteShare_'+a.key]/100)}));
 const commuteTotal=commuters.reduce((t,a)=>t+a.commuters,0);
 const busKm=s.busKmPerDay*s.busDays,busGross=busKm*s.busCostPerKm,busNet=busGross-s.transportOffsets;
 const selectedGross=housing+(cumulativeTax+cumulativeDriving)/1e6;
 return {local,homes,housing,km,fuel,otherCar,driving,adultHours,pupilHours,perHouseholdTax,netDepartures,grossTax,cumulativeTax,cumulativeDriving,selectedGross,commuters,commuteTotal,busKm,busGross,busNet};
}
