function syncSelect(id,value,label){const el=document.getElementById(id);Array.from(el.options).filter(o=>o.dataset.custom).forEach(o=>o.remove());if(!Array.from(el.options).some(o=>Number(o.value)===value)){const option=document.createElement('option');option.value=String(value);option.textContent=label;option.dataset.custom='true';el.appendChild(option);}el.value=String(value);}
function renderDashboard(){
 result=calculate(state);const r=result;
 document.getElementById('point-grid').innerHTML=points.map((p,i)=>`<button class="point" data-open="${p.id}"><div class="point-top"><span class="point-num">${String(i+1).padStart(2,'0')}</span><span class="tag ${p.type==='scenario'?'scenario':''}">${p.type}</span></div><h3>${esc(p.title)}</h3><div class="point-value">${esc(p.value(r))}</div><p>${esc(p.text(r))}</p><span class="arrow">Öppna fråga ${i+1} ↗</span></button>`).join('');
 document.getElementById('question-list').innerHTML=points.map((p,i)=>`<li><b>${i+1}.</b> ${esc(p.question)}</li>`).join('');
 updatePanelFigures();
}
const configs={drop:{label:'Prisfall, %',max:100,step:.5},departures:{label:'Hushåll som flyttar ut',max:10000,step:1},newHouseholds:{label:'Tillkommande hushåll i scenariot',max:10000,step:1},years:{label:'Beräkningsperiod, år',min:1,max:50,step:1},ramp:{label:'År tills utflyttningen fått full effekt',max:50,step:1},childPerHousehold:{label:'Elever per skolfamilj i uppskattningarna',min:.1,max:10,step:.1},familyShare:{label:'Andel bostadshushåll med skolelever, %',min:1,max:100,step:1},drivingHouseholds:{label:'Kvarvarande hushåll med extra bilresor',max:10000,step:1},kmPerDay:{label:'Extra kilometer per hushåll och dag',max:500,step:1},drivingDays:{label:'Resdagar per år',max:365,step:1},litersPerMil:{label:'Liter drivmedel per mil',max:5,step:.05},fuelPrice:{label:'Drivmedelspris, kr/liter',max:100,step:.5},otherCostPerKm:{label:'Övrig rörlig bilkostnad, kr/km',max:30,step:.1},adultMinutes:{label:'Extra minuter per hushåll och dag',max:600,step:1},pupilMinutes:{label:'Extra minuter per elev, enkel väg',max:180,step:1},schoolDays:{label:'Skoldagar per år i scenariot',max:365,step:1},taxpayers:{label:'Skattebetalare per hushåll',max:10,step:.1},taxableIncome:{label:'Beskattningsbar inkomst per person, kr/år',max:10000000,step:1000},taxRate:{label:'Kommunal skattesats, %',max:100,step:.01}};
Object.assign(configs,{busKmPerDay:{label:'Extra buss-km per dag, hela nätet',max:10000,step:1},busDays:{label:'Bussdagar per år',max:365,step:1},busCostPerKm:{label:'Antagen merkostnad, kr per extra buss-km',max:1000,step:1},transportOffsets:{label:'Årliga besparingar att dra av, kr',max:100000000,step:1000}});
areas.forEach(a=>{configs['commuteShare_'+a.key]={label:a.name+': andel skolfamiljer till angivna arbetsorter, %',max:100,step:1};configs['homes_'+a.key]={label:a.name+': uppskattade bostäder',max:100000,step:1};configs['price_'+a.key]={label:a.name+': snittvärde, mkr',max:1000,step:.1};});
function field(key){const c=configs[key];return `<label>${esc(c.label)}<input type="number" data-setting="${key}" aria-label="${esc(c.label)}" value="${state[key]}" min="${c.min??0}" max="${c.max}" step="${c.step}"></label>`;}
function fields(keys){return `<div class="fields">${keys.map(field).join('')}</div><div class="error field-error" role="status"></div>`;}
function section(title,keys){return `<section class="field-section"><h3>${title}</h3>${fields(keys).replaceAll('id="field-error"','class="field-error"')}</section>`;}
function source(url,label){const municipal=url.includes('tidaholm.se');return `<a class="source-link ${municipal?'municipal-source':''}" href="${url}" target="_blank" rel="noopener">${municipal?'Läs kommunens underlag om detta ämne här ↗<small>'+esc(label)+'</small>':esc(label)+' ↗'}</a>`;}
function question(id){const index=points.findIndex(p=>p.id===id),p=points[index];return `<div class="question primary-question"><strong>FRÅGA ${index+1} TILL KOMMUNEN</strong>${esc(p.question)}</div>`;}
function housingTable(){return `<table class="mini-table"><thead><tr><th>Område</th><th>Elever</th><th>Estimerade bostäder</th><th>Värdefall</th></tr></thead><tbody>${result.local.map(a=>`<tr><td>${a.name}</td><td>${a.pupils}</td><td>${integer(a.homes)}</td><td>${nf(a.loss)} mkr</td></tr>`).join('')}</tbody></table>`;}
function commuteTable(){return `<table class="mini-table commute-table"><thead><tr><th>Skolområde / arbetsorter</th><th>Hushåll i scenariot</th></tr></thead><tbody>${[result.commuters[1],result.commuters[0],result.commuters[2]].map(a=>`<tr><td><b>${a.name}</b><small>${destinations[a.key]}</small></td><td>${a.commuters}<small>${state['commuteShare_'+a.key]} % av cirka ${a.families} skolfamiljer</small></td></tr>`).join('')}</tbody></table>`;}
function researchCards(){return `<div class="research-cards"><article><span>DANMARK · ÅTTA BYSKOLOR</span><h3>7,6 procentenheter svagare befolkningsutveckling</h3><p>Studien av Tønders nedläggningar 2011 jämförde med kontrollorter och utvecklingen före nedläggning. Skillnaden avser en tioårsperiod.</p>${source(DENMARK,'Sørensen m.fl. 2021 · originalstudien')}</article><article><span>USA · CEDAR FALLS, IOWA</span><h3>Lägre bostadsvärden efter stängningen</h3><p>Rosburg m.fl. skattade ett prisfall på 6,8–7,2 %, beroende på modell, efter att en offentlig skola stängde. Skolvalsrätten var knuten till bostaden, vilket gör fallet speciellt.</p>${source(IOWA,'Rosburg m.fl. 2017 · originalstudien')}</article><article><span>DANMARK · BALLUM</span><h3>Lokala nätverk försvagades</h3><p>En jämförande fallstudie beskrev förlust av socialt kapital efter skolstängningen: bygdens samarbete och kontakter påverkades.</p>${source(NETWORKS,'Svendsen & Svendsen 2018 · originalstudien')}</article></div><p class="small">Erfarenheter som motiverar en lokal konsekvensanalys. Forskningen är inte entydig; exemplen bevisar varken ett visst prisfall eller ett visst antal utflyttade hushåll i Tidaholm. Kalkylens 20 % är ett eget riskantagande.</p>`;}
function panelBodyHTML(id){const r=result;
 if(id==='housing')return `<h2>Husens värdeminskning</h2><div class="detail-value" data-live="housing">${nf(r.housing)} mkr</div><p>Antaget prisfall: <b data-live="drop">${state.drop} %</b>. Bostadsestimatet gäller skolområden, inte enbart orternas kärnor.</p><div id="housing-table">${housingTable()}</div>${fields(['drop','homes_fro','price_fro','homes_val','price_val','homes_eke','price_eke'])}<div class="formula">Bostäder × snittvärde × prisfall. Startvärden: 1,6 elever per hushåll och 40 % hushåll med skolelever. Antalet avrundas uppåt per område. 2 mkr per bostad är ett scenario, inte ett verifierat lokalt medelpris.</div><div class="field-section"><h3>Bostadsestimatets antaganden</h3>${fields(['childPerHousehold','familyShare']).replace('id="field-error"','class="field-error"')}<button class="edit-button" data-action="estimate">Räkna om bostadsantalet från elevmodellen</button></div><p class="note">Elevantal kan inte fastställa bostadsbeståndet. Modellen är en grov uppskattning; påverkat geografiskt område, bostadstyp och faktiska priser behöver undersökas. Värdefallet är en tillgångsförändring för ägarna, inte en årlig kostnad.</p>${source(PDF+'#page=17','Elevantal ht 2026 · PDF-sida 17')}${source('https://www.hemnet.se/salda/hus/tidaholms-kommun','Exempel på faktiska lokala försäljningar · visar inte ett genomsnitt')}${question(id)}`;
 if(id==='driving')return `<h2>Extra bilresor till förskolan</h2><div class="detail-value" data-live="driving">${nf(r.driving/1e6,2)} mkr/år</div><p>Startscenariot utgår från 35 kvarvarande hushåll: 25 respektive 19 förskolebarn delat med antagna 1,3 förskolebarn per hushåll, avrundat uppåt per förskola.</p>${fields(['drivingHouseholds','kmPerDay','drivingDays','litersPerMil','fuelPrice','otherCostPerKm'])}<div class="formula" id="driving-formula"></div><p class="note">Extra körsträcka avser omvägen utöver resor som ändå skulle göras. Förbrukning, pris och övrig rörlig bilkostnad är scenarioantaganden. Övrig bilkostnad ska exkludera drivmedel. Hushållen här antas bo kvar hela perioden; utflyttade hushåll ingår inte i deras reskostnad.</p>${source(PDF+'#page=16','Förskolebarn ht 2026 · PDF-sida 16')}${question(id)}`;
 if(id==='time')return `<h2>Föräldrarnas extra restid</h2><div class="detail-value" data-live="adultHours">${integer(r.adultHours)} timmar/år</div><p>Tid för extra omvägar vid lämning och hämtning. Den värderas inte i kronor eller läggs till bruttosumman.</p>${fields(['drivingHouseholds','adultMinutes','drivingDays'])}<div class="formula">Hushåll × extra minuter per dag × resdagar ÷ 60.</div>${question(id)}`;
 if(id==='childtime')return `<h2>Barnens extra restid</h2><div class="detail-value" data-live="pupilHours">${integer(r.pupilHours)} timmar/år</div><p>252 elever × extra minuter enkel väg × 2 resor × skoldagar. Antagandet gäller alla elever i modellen; faktiska resor kan skilja sig mellan elever. Tid är inte en kommunal budgetkostnad.</p>${fields(['pupilMinutes','schoolDays'])}${source(PDF+'#page=17','Elevantal ht 2026 · PDF-sida 17')}${question(id)}`;
 if(id==='migration')return `<h2>Utflyttning och skatteintäkter</h2><div class="detail-value" data-live="grossTax">${nf(r.grossTax/1e6,2)} mkr/år</div><p>Minskade egna bruttointäkter när den antagna nettoförlusten av hushåll fått full effekt.</p><p>När familjen redan arbetar utanför kommunen kan en nedlagd skola eller förskola bli ett skäl att flytta närmare jobbet. Då riskerar Tidaholm att förlora både dagens invånare och framtida lokalt engagemang.</p><button class="text-button" data-open="commuting">Se pendlingen och risken för flytt till arbetskommunen ↗</button>${fields(['departures','newHouseholds','ramp','years','taxpayers','taxableIncome','taxRate'])}<div class="formula" id="migration-formula"></div><p class="note">50 utflyttade hushåll och noll tillkommande är användarens startscenario. Inkomst och antal skattebetalare är antaganden. Utflyttningen ökar linjärt till vald nivå. Flytt inom Tidaholm ger inte denna skatteeffekt. Beloppet är före kommunalekonomisk utjämning, statsbidrag och förändrade verksamhetskostnader.</p>${source(BUDGET+'#page=14','Skattesats 22,07 % · kommunens budget, PDF-sida 14')}${source(EQUALIZATION,'SCB · utjämning förändrar kommunens nettoeffekt')}${question(id)}`;
 if(id==='children')return `<h2>296 barn i berörda verksamheter</h2><table class="mini-table"><thead><tr><th>Område</th><th>Skolelever</th><th>Förskolebarn</th></tr></thead><tbody>${areas.map(a=>`<tr><td>${a.name}</td><td>${a.pupils}</td><td>${a.preschool||'Förskolan föreslås behållas'}</td></tr>`).join('')}<tr><td>Summa berörda</td><td>252</td><td>44</td></tr></tbody></table><p>Förslaget avser de tre skolorna och förskolorna i Valstad och Fröjered. Antalen är från tabellerna daterade 30 september 2026.</p>${source(PDF+'#page=16','Barnantal · PDF-sidor 16–17')}${question(id)}`;
 if(id==='comparison')return `<h2>Kostnadsargumentet gäller inte lika för alla</h2><table class="mini-table"><tr><th>Skola</th><th>Redovisad kostnad per elev 2025</th></tr><tr><td>Valstad</td><td>99 269 kr</td></tr><tr><td>Rosenberg</td><td>101 425 kr</td></tr></table><p>Valstad kostar 2 156 kr mindre per elev i denna jämförelse. Därför räcker inte en generell beskrivning av små skolor som dyrare för att motivera varje enskild nedläggning.</p><p class="note">Fördelade kostnader, exklusive centrala kostnader och fritidshem. Genomsnitt visar inte mottagande skolors marginalkostnad.</p>${source(PDF+'#page=49','Kommunens kostnadstabell · PDF-sida 49')}${question(id)}`;
 if(id==='classes')return `<h2>Vilka klasser får barnen?</h2><div class="detail-value">Klasstorlek måste redovisas</div><p><b>Lediga platser i en byggnad visar inte barnens verkliga vardag.</b> Kommunen behöver redovisa faktiska klasser och barngrupper, bemanning, matsal, skolgård, fritidshem och lugna arbetsplatser efter flytten.</p><p>IFAU:s studie av årskurs 4–6 fann att mindre klasser förbättrade förmågor vid 13 års ålder, provresultat vid 16 samt utbildningsnivå och lön i vuxen ålder.</p>${source(IFAU,'IFAU · Långsiktiga effekter av mindre klasser, rapport 2012:5')}<p>En internationell forskningsöversikt av 57 studier fann att den samlade evidensen övervägande talade för mindre skolor, särskilt för elever som har svårare i skolan och elever med svagare socioekonomiska förutsättningar. Det är inte ett bevis för att varje liten skola är bättre, men det motsäger att större automatiskt betyder högre kvalitet.</p>${source(SCHOOL_SIZE_REVIEW,'Leithwood & Jantzi 2009 · forskningsöversikt')}<div class="question"><strong>UNDERLAG SOM BEHÖVS</strong>Antal elever per klass och barngrupp före och efter, undervisande lärare, vuxna per barn, specialpedagogiskt stöd och hur lokalerna används under hela dagen.</div><div class="field-section"><h3>Regeringen utreder klasstorlek och lärartäthet</h3><p>Den 27 augusti 2026 tillsattes en utredning om lämpliga klasstorlekar och lärartäthet. Förslagen ska redovisas senast 28 januari 2028.</p><p>Hur påverkar detta skolorganisationen som kommunen föreslår ska förändras hösten 2028?</p>${source(GOVERNMENT,'Regeringens besked · 27 augusti 2026')}${source(CLASS_INQUIRY,'Kommittédirektiv 2026:96')}</div><p class="note">Skolans elevantal, byggnadens maxkapacitet och klassens storlek är tre olika mått. Studierna visar inte effekten av just Tidaholms förslag och anger ingen automatisk lokal lösning.</p>${question(id)}`;
 if(id==='safety')return `<h2>Vem ser barnet i den nya skolmiljön?</h2><p>Skolverket lyfter relationer mellan lärare och elever som betydelsefulla för trygghet och lärande. SPSM lyfter ljudmiljö, koncentration, arbetsro och möjlighet till återhämtning.</p><p><b>Kapacitet ska därför visas i praktiken, inte bara som antal möjliga elevplatser.</b> Redovisningen behöver omfatta samtidiga elever, vuxennärvaro, gruppstorlek, ljudnivåer, stödutrymmen och hur miljön fungerar under raster, måltider och fritidshem.</p><div class="learning-detail"><h3>Trygga relationer</h3><p>Vilka kända lärare och andra vuxna följer med barnen? Hur säkras kontinuiteten för barn som redan behöver stöd?</p><h3>Vuxennärvaro och överblick</h3><p>Hur många elever delar skolgård och matsal samtidigt? Vilka vuxna har ansvar för att upptäcka ensamhet, konflikter och otrygghet?</p><h3>Ljud, trängsel och återhämtning</h3><p>Vilka lugna rum och anpassningar finns? Hur bedöms ljudmiljön i klassrum, korridorer och matsal före och efter förändringen?</p><h3>Stöd för elever med större behov</h3><p>Hur säkras individuella anpassningar, tillgång till elevhälsa och möjlighet till ett mindre sammanhang?</p></div>${source(RELATIONS,'Skolverket · relationer och trygg lärmiljö')}${source(ENVIRONMENT,'SPSM · fysisk lärmiljö, arbetsro och återhämtning')}${source(PDF+'#page=30','Kommunens beskrivning av mottagande verksamheter · PDF-sida 30')}<p class="note">Detta är konkreta riskfrågor vid en skolövergång. Källorna belägger inte att alla stora skolor är sämre eller att dessa problem säkert uppstår i Tidaholm.</p>${question(id)}`;
 if(id==='society')return `<h2>Utredningen lämnar samhällseffekter utanför</h2><p>Samhällsekonomiska och regionalpolitiska konsekvenser avgränsas bort. Därför visar skolutredningen inte hela effekten på bostadsmarknad, bygdens attraktivitet och lokala nätverk.</p>${source(PDF+'#page=8','Utredningens avgränsning · PDF-sida 8')}<h3>Samlad scenarioöversikt</h3><div class="detail-value" data-live="selectedGross">${nf(r.selectedGross)} mkr</div><table class="mini-table" id="total-table"><tr><td>Bostadsvärden · en gång</td><td>${nf(r.housing)} mkr</td></tr><tr><td>Extra bilkostnad · ${state.years} år</td><td>${nf(r.cumulativeDriving/1e6,2)} mkr</td></tr><tr><td>Egna bruttoskatteintäkter · successivt</td><td>${nf(r.cumulativeTax/1e6,2)} mkr</td></tr><tr><td>Valda bruttobelopp</td><td>${nf(r.selectedGross)} mkr</td></tr></table><p><b>Detta är en översikt över tre olika effekter för olika aktörer.</b> Bostadsvärden gäller ägarna, bilkostnader hushållen och bruttoskatt kommunen. Beloppet är därför inte en kommunal eller samhällsekonomisk nettokostnad.</p><p class="note">Besparingar, kommunalekonomisk utjämning, statsbidrag, förändrade offentliga kostnader, tidsåtgång och effekter i andra kommuner är inte avräknade. Värdefallet räknas en gång; övriga poster över vald period. Antagandena ändras i frågorna om bostäder, resor och utflyttning.</p><p>Skolbudgetens besparing och hushållens kostnader behöver behandlas som olika delar av samma beslut.</p>${question(id)}`;

 if(id==='transport')return `<h2>Redovisa hela skolskjutsen</h2><p><b>Kommunen medger en ökad skolskjutskostnad.</b> Den räknar ändå nettoeffekten som noll eftersom undervisningsresor och viss skolanknuten personal väntas kosta mindre. En nolla är därför ett antagande om motposter — inte ett bevis på kostnadsneutralitet.</p><h3>Rapportens ±0 bygger på motposter utan redovisade belopp</h3><table class="mini-table"><tr><th>Post i kommunens resonemang</th><th>Belopp i rapporten</th></tr><tr><td>Ökad skolskjuts</td><td>Inte angivet</td></tr><tr><td>Minskade undervisningsresor</td><td>Inte angivet</td></tr><tr><td>Minskad skolanknuten personal</td><td>Inte angivet</td></tr><tr><td><b>Redovisad nettoeffekt</b></td><td><b>±0 kr</b></td></tr></table><p>För att netto ±0 ska kunna granskas behöver kommunen visa varje ökad transportkostnad och exakt vilka kostnader som försvinner, med belopp och budgetrad. Annars går det inte att kontrollera om motposterna är lika stora, möjliga att genomföra eller redan räknade som besparing någon annanstans.</p>${source(PDF+'#page=62','Kommunens transportantagande · PDF-sidor 62, 65 och 68')}<table class="mini-table"><tr><th>Skola</th><th>Elever</th><th>Skolskjuts idag</th></tr><tr><td>Valstad</td><td>97</td><td>58</td></tr><tr><td>Fröjered</td><td>47</td><td>23</td></tr><tr><td>Ekedalen</td><td>108</td><td>51</td></tr><tr><td>Totalt</td><td>252</td><td>132</td></tr></table><p>Redan 132 elever har skolskjuts. De övriga 120 är inte automatiskt 120 nya skolskjutselever. Rätt till skolskjuts, nya resvägar och kapacitet måste bedömas elev för elev.</p>${source(PDF+'#page=18','Skolskjutselever 9 september · PDF-sida 18')}<h3>Det här ska kommunen lägga fram</h3><ul class="detail-list"><li>Turer, hållplatser, reslängd, väntetid och tidigaste hämtning före och efter, per område och årskurs.</li><li>Fordon, sittplatser, antal samtidiga turer, tomkörning, reservlösningar och tillgång till fritidsresor.</li><li>Avtalspriser, fasta fordonskostnader, extra förartimmar och kostnad för ändrade turer.</li><li>Undervisningsresor och personalposter som försvinner: belopp, budgetrad, år och varför samma behov inte kvarstår på mottagande skola.</li><li>Kostnadsintervall vid andra elevtal, bränslepriser och avtalsvillkor — samt vem som bär risken.</li></ul><p>Rapporten beskriver själv att fler elever kan behöva skolskjuts och att ekonomi och organisation behöver beaktas. Före beslutet behövs en körbar trafikplan och en spårbar kostnadskalkyl.</p>${source(PDF+'#page=30','Utredningens transportkonsekvenser · PDF-sida 30')}<div class="field-section"><h3>Testa vad som krävs för ±0</h3><p>Illustration med ifyllda antaganden. Körningen är <b>ökningen mot dagens trafik</b>, inklusive tomkörning. 45 kr/km är en antagen samlad merkostnad, inte ett avtalspris.</p>${fields(['busKmPerDay','busDays','busCostPerKm','transportOffsets'])}<div class="formula" id="bus-formula"></div><p class="note">Ingen offert eller verifierad lokal trafikplan finns i denna modell. Fasta nya fordonskostnader kan behöva läggas till. Exemplet ingår inte i sidans bruttosumma. Kommunens motposter måste styrkas med underlag.</p></div>${question(id)}`;
 if(id==='commuting')return `<h2>Omvägen kan få familjer att flytta</h2><div class="question migration-demand"><strong>RISKEN FÖR TIDAHOLM</strong>En familj som redan arbetar i en annan kommun kan börja överväga att också bo där. Om den lokala skolan och förskolan försvinner kan ett viktigt skäl att bo kvar försvagas.</div><p>En omväg till Tidaholm för lämning och sedan vidare till arbetet kan göra en flytt till arbetskommunen mer lockande. Där kan familjen försöka samla bostad, arbete, skola och förskola i en enklare vardag.</p><p><b>Flyttrisken behöver bedömas för Falköping, Mullsjö och Jönköping från Valstad; Skövde och Hjo från Fröjered; samt Falköping och Skövde från Ekedalen.</b> Förlusten för kommunen kan bli varaktig när familjen byter bostadsort.</p><button class="edit-button" data-open="migration">Testa utflyttningens skatteeffekt ↗</button><h3>Pendlingen som behöver kartläggas</h3><p>Kommunövergripande statistik visar att arbetsorterna är relevanta: år 2022 pendlade 899 personer till Skövde, 530 till Falköping, 143 till Jönköping, 129 till Hjo och 81 till Mullsjö. Detta gäller alla invånare, inte föräldrar vid en viss skola.</p>${source(COMMUTING+'#page=18','Företagarfakta 2024 · pendling 2022, PDF-sida 18')}<div id="commute-table">${commuteTable()}</div><p><b>Uppskattning, inte en kartläggning.</b> Elevantal ÷ antagna 1,6 elever per hushåll, avrundat uppåt. Därefter antas 40 % av skolfamiljerna ha minst en förälder som arbetar i någon av de angivna orterna. Andelen är ett valt räkneantagande; arbetsorterna inom varje grupp är inte fördelade.</p>${fields(['childPerHousehold','commuteShare_val','commuteShare_fro','commuteShare_eke'])}<p class="note">Modellen räknar hushåll, inte personer. Den omfattar inte extra hushåll med enbart förskolebarn; de kan överlappa skolfamiljer. Uppskattade pendlingshushåll är inte ett antal familjer som kommer att flytta. De läggs varken till utflyttningsscenariot eller som nya resehushåll eller en ny kostnad. Elevbaserade hushållstal påverkas av syskon och delat boende.</p><div class="question"><strong>EN KONKRET REDOVISNING BEHÖVS</strong>Anonym enkät: bostadsområde, arbetsort, arbetstid, barnens nya skola/förskola, nuvarande och framtida dörr-till-dörr-resa. Fråga särskilt om familjen skulle överväga att flytta till arbetskommunen om skolan eller förskolan stänger, och vilka förändringar som skulle avgöra beslutet. Reskedjor, skiftarbete och delat boende ger sammanhang till svaren.</div><p>Enkäten behöver skilja allvarligt övervägande från en allmän oro och en konkret flyttplan. Kalkylens 50 utflyttade hushåll är ett redigerbart riskscenario, inte ett resultat från pendlingsstatistiken.</p>${question(id)}`;
 if(id==='examples')return `<h2>Vad har hänt på andra platser?</h2>${researchCards()}<p>En svensk studie av två landsbygdsskolor visar hur en lokal skola fungerar som nav i familjers vardag och lokalsamhället, och hur nedläggning förändrar vardagsliv och relationer. En dansk studie fann kortsiktigt försämrade provresultat för elever från nedlagda skolor, med störst negativ effekt för elever som kom från små skolor.</p>${source(VILLAGE_SCHOOL,'Cedering & Wihlborg 2020 · svensk originalstudie')}${source(DENMARK_RESULTS,'Beuchert m.fl. · dansk originalstudie')}<p>En finländsk studie med data 2010–2018 fann också en mer negativ befolkningsutveckling i områden där skolor stängdes. Geografi, alternativ och tidsperiod påverkar hur jämförbara fallen är.</p>${source(FINLAND,'Lehtonen 2021 · Finland')}<p class="note">Studier från andra platser visar riskmekanismer, inte exakt vad som kommer att hända i Tidaholm. Därför behövs en lokal analys före beslutet.</p>${question(id)}`;
 if(id==='rural')return `<h2>Bygdens jobb och vardag påverkas</h2><p><b>Skolan och förskolan är också lokala arbetsplatser.</b> Lärare, förskollärare, barnskötare, fritidspersonal, kök, städning, vaktmästeri och underhåll berörs när verksamheten flyttas. Lokala arbetsplatser kan försvinna även om anställningarna finns kvar i kommunen.</p><div class="field-section"><h3>Arbetsplatser och uppdrag som ska redovisas</h3><table class="mini-table jobs-table"><thead><tr><th>Arbete</th><th>Det som ska redovisas</th></tr></thead><tbody><tr><td>Lärare, förskollärare och barnskötare</td><td>Vilka tjänster följer med, byter ort eller faktiskt upphör?</td></tr><tr><td>Fritids- och resurspersonal</td><td>Vad händer med bemanning, elevassistenter och tillfälliga tjänster?</td></tr><tr><td>Kök, måltider och städning</td><td>Hur ändras lokala arbetstimmar, avtal och behov på mottagande skola?</td></tr><tr><td>Vaktmästeri och underhåll</td><td>Vilka återkommande uppdrag försvinner och vad behövs i kvarvarande lokaler?</td></tr><tr><td>Lokala entreprenörer</td><td>Vad händer med reparationer, service, utemiljö, snöröjning och leveranser?</td></tr></tbody></table><p>Visa personer, årsarbetare, lokala entreprenadtimmar och inköp före och efter. Skilj arbetsplatser som flyttas inom kommunen från anställningar som upphör och uppdrag som dras in.</p>${source(PDF+'#page=62','Personalantagandet · PDF-sidor 62, 65, 68, 71 och 73')}</div><p>När barn flyttas till olika skolor längre bort kan deras vardagskontakter spridas. Föräldrar möts mer sällan lokalt. Barn kan bli mer beroende av skjuts till både kompisar och aktiviteter.</p><p>Fallstudien från Ballum beskriver förlust av lokalt socialt kapital efter stängningen. Det är en konkret risk för samarbete, föreningsliv och engagemang som en skolbudget inte fångar.</p>${source(NETWORKS,'Fallstudie · lokala nätverk efter skolstängning')}<ul class="detail-list"><li>Vem kan fortfarande gå eller cykla till skolan och träffa kompisar själv?</li><li>Vilka lokaler och lokala möten försvinner för föreningar och föräldrar?</li><li>Hur fungerar aktiviteter när bussarna och fritidshemmen har andra tider?</li><li>Vad betyder förlusten av både skola och förskola för nästa familj som vill bosätta sig i bygden?</li></ul><p class="note">Lokala följder behöver kartläggas. Exemplen visar möjliga mekanismer, inte att varje effekt säkert uppstår här.</p>${question(id)}`;
 if(id==='hidden')return `<h2>Besparingen måste följas hela vägen</h2><p>Redovisa kostnader och ansvar för mottagande skolors kapacitet, fritidshem, anpassningar, skolövergången och lokaler som lämnas. Skilj engångsbelopp från varaktiga besparingar.</p><ul class="detail-list"><li>Behövs fler rum, personal, måltidsplatser, stödinsatser eller trafikåtgärder?</li><li>Vad kostar flytt, uppstart, information och övergångsstöd?</li><li>När upphör avtal, uppvärmning, tillsyn och underhåll i de gamla lokalerna?</li><li>Vilka besparingar bygger på en försäljning som ännu inte är genomförd?</li></ul><p>De 20 mindre följderna på sidan är en kontrollista för ansvar och omfattning. De är inte 20 nya kostnadsposter att automatiskt lägga ihop med kalkylen.</p>${question(id)}`;
 if(id==='traffic')return `<h2>Fler skjutsar kräver en säker trafikplan</h2><div class="question migration-demand"><strong>TRAFIKSÄKERHET FÖRE BESLUTET</strong>Kommunen behöver visa hur fler bilar och bussar ska hanteras vid mottagande skolor. Barnens gång- och cykelvägar, avlämning och hämtning måste fungera även när många anländer samtidigt.</div><p>En förälder beskriver redan idag stora trafikproblem runt skolan. Det är en lokal uppgift som behöver följas upp med observationer och mätningar. Den ger skäl att undersöka nuläget innan mer trafik koncentreras dit.</p><p>Trafikverket beskriver i ett skolvägsprojekt på Gotland hur skjutsande föräldrar ökar trafiken och försämrar säkerheten vid skolorna. Det är ett belagt riskexempel; de lokala förhållandena i Tidaholm måste kartläggas.</p>${source(SCHOOL_TRAFFIC,'Trafikverket · trafik vid hämtning och lämning')}<h3>Redovisa innan fler barn flyttas dit</h3><ul class="detail-list"><li><b>Nuläge och nytt läge:</b> räkna bilar, bussar, gående och cyklister under lämning och hämtning vid varje mottagande skola.</li><li><b>Konfliktpunkter:</b> kartlägg korsande trafik, backning, dubbelparkering, skymd sikt och barn som passerar bussar eller köer.</li><li><b>Trängsel och tid:</b> visa kölängder, väntetider, angöringsplatser och var trafiken tar vägen när platserna är fulla.</li><li><b>Säkra vägar:</b> redovisa hur barn till fots och på cykel skyddas vid övergångar, hållplatser och entréer, även i mörker och vinterväglag.</li><li><b>Ombyggnad av vägnätet:</b> pröva behovet av nya avlämningsplatser, bussfickor, vändytor, gång- och cykelvägar, korsningar, hastighetsåtgärder och ändrad gatuföring.</li><li><b>Kostnad och tidplan:</b> vem är väghållare, behövs mark eller tillstånd, vad kostar investering och drift, och är åtgärderna klara innan skolorganisationen ändras?</li></ul>${source(SAFE_ROUTES,'Trafikverket · planering för trafiksäkra skolresor')}<p><b>Om trafikåtgärder behövs för att genomföra flytten ska de redovisas i beslutets totala kalkyl.</b> Visa vilka som redan ingår och vilka som ligger utanför skolbudgeten.</p>${question(id)}<div class="field-section"><h3>Extra trafik och vägslitage · separat räkneexempel</h3></div><div class="detail-value" data-live="busKm">${integer(r.busKm)} buss-km/år</div><p>Extra körning i hela det antagna skolskjutsnätet: ${state.busKmPerDay} km/dag × ${state.busDays} dagar. Trafikplanen måste visa hur mycket som faktiskt tillkommer mellan skolområdena och Tidaholm.</p>${fields(['busKmPerDay','busDays'])}<div class="formula" id="traffic-formula"></div><p>Vägslitage behöver bedömas med fordonens axellaster, befintlig trafik, vägens konstruktion och sträckornas väghållare. Ett extra buss-kilometer och ett extra bil-kilometer ger inte samma slitage.</p><p class="note">Här sätts inget påhittat kronbelopp på vägarna. Bilkilometrarna avser hushållens hela extra omväg, inte enbart vägen till Tidaholm. Förbrukning och bilslitage ingår redan i bilkalkylen; dessa räknas inte igen. Bussexemplet omfattar en ökning mot dagens nät och undviker att räkna hela den befintliga trafiken som ny.</p><p>Begär även bedömning av trafiksäkerhet vid hållplatser, vinterväghållning, buller, utsläpp, köer och hämtning vid mottagande skolor.</p>`;

 if(id==='movement')return `<h2>När skolvägen slutar ge rörelse</h2><p>För barn som idag går eller cyklar kan skolresan ge återkommande vardagsmotion. Om hela resan ersätts av buss blir den delen av dagen mer stillasittande. Hälsan behöver därför ingå i konsekvensanalysen.</p><h3>Fakta: rörelse behövs varje dag</h3><p>Folkhälsomyndigheten rekommenderar att barn och unga 6–17 år i genomsnitt får minst 60 minuter pulshöjande fysisk aktivitet per dag. Längre perioder av stillasittande bör brytas.</p>${source(MOVEMENT,'Folkhälsomyndigheten · fysisk aktivitet och stillasittande')}<p>Trafikverkets underlag lyfter hälsa och barns självständighet när skolresor sker till fots eller på cykel. Förlusten av en aktiv skolväg kan både minska rörelsen och öka beroendet av transporter.</p>${source(SAFE_ROUTES,'Trafikverket · barns aktiva skolresor')}<h3>Exempel på vad som kan gå förlorat</h3><div class="formula">Ett barn går 10 minuter till skolan och 10 minuter hem. Om promenaden ersätts helt av buss försvinner 20 minuters gång per skoldag. Det är ett exempel, inte en uppmätt lokal effekt.</div><p>Om fler elever anländer med buss och bil behöver också trafiken kring mottagande skolor hanteras. Hälsa och trafiksäkerhet är två delar av samma förändring.</p><div class="mini-actions"><button class="text-button" data-open="traffic">Se frågan om trafik och trängsel ↗</button></div><h3>Underlag som behövs</h3><ul class="detail-list"><li>Antal barn som går eller cyklar idag och hur deras resa förändras.</li><li>Minuter i rörelse före och efter, inklusive gång till hållplatsen.</li><li>En konkret plan för att förebygga minskad rörelse och ökat stillasittande.</li></ul>${source(PDF+'#page=30','Kommunens transportavsnitt · PDF-sida 30')}<p class="note">Det faktiska bortfallet beror på resväg och kvarvarande gångsträcka. Underlagen visar varför rörelse behöver bedömas; de bevisar inte att varje berört barn kommer att utveckla ett hälsoproblem.</p>`;
 if(id==='recovery')return `<h2>Längre resdagar tar tid och ork</h2><p>Tidigare bussavgång kan kräva tidigare uppstigning. Senare hemkomst lämnar mindre utrymme för lek, träning, föreningsliv, läxor och återhämtning. Väntetid ska räknas med, inte bara minuterna på bussen.</p><h3>Sömn och koncentration</h3><p>1177 beskriver att barn som får för lite sömn under en period kan få sämre minne och koncentration och svårare att lära sig nya saker. En tidigare morgon behöver därför bedömas tillsammans med barnets möjlighet att sova tillräckligt.</p>${source(CHILD_SLEEP,'1177 · hur barn påverkas av sömnbrist')}<h3>Testa extra restid</h3><div class="detail-value" data-live="pupilHours">${integer(r.pupilHours)} timmar/år</div><p>Samlad extra restid för 252 elever i sidans scenario. Alla elever antas här få samma ökning; faktiska resdagar behöver kartläggas individuellt.</p>${fields(['pupilMinutes','schoolDays'])}<div class="formula">Exempel: 20 minuter extra enkel väg ger 40 minuter mindre disponibel tid per skoldag, eller 3 timmar och 20 minuter under fem skoldagar. Det är ett räkneexempel, inte en fastställd tidtabell.</div><h3>Redovisa barnets hela dag</h3><ul class="detail-list"><li>Tidigaste uppstigning, hämtning, skolstart, väntan och hemkomst per område och ålder.</li><li>Vilka aktiviteter barnen hinner till och hur fritidshem och bussturer fungerar tillsammans.</li><li>Hur sömn, trötthet och ork följs upp med barnen och elevhälsan.</li></ul>${source(PDF+'#page=30','Kommunens transportavsnitt · PDF-sida 30')}<p class="note">Längre resor innebär inte automatiskt sömnbrist. Risken behöver bedömas från verkliga tider och följas upp. Barnens restid är redan med i tidsscenariot och räknas inte en gång till i bruttosumman.</p>`;
 if(id==='caraccess')return `<h2>Alla familjer har inte en bil tillgänglig</h2><p>En lösning som går att hantera med egen bil kan bli betydligt svårare för ett bilfritt hushåll eller en ensamstående förälder. Fler avstånd kan göra barnens möjligheter beroende av vuxnas transport och arbetstider.</p><h3>Ett vardagsexempel</h3><p>Barnet behöver hämtas tidigare, stanna på fritids eller ta sig till en aktivitet efter skolan. Om det inte passar bussturen behöver familjen en annan lösning. För en förälder utan bil eller möjlighet att lämna arbetet kan det bli svårt.</p><h3>Kommunen behöver visa hur det fungerar</h3><ul class="detail-list"><li>Vilka alternativ som finns utanför de ordinarie skolbussarnas tider.</li><li>Hur hämtning, fritidshem och resor vid ändrade tider fungerar för berörda familjer.</li><li>Vilka grupper som får större hinder att delta och vad kommunen gör åt dem.</li></ul>${source(PDF+'#page=30','Kommunens transportavsnitt · PDF-sida 30')}<p class="note">Det här är en riskfråga om tillgänglighet. Omfattningen beror på faktiska turer, familjers förutsättningar och tillgängliga alternativ.</p>`;
 if(id==='friends')return `<h2>Den spontana leken kan bli svårare</h2><p>När skola, fritidshem och kompisar finns längre bort kan barn få svårare att träffas spontant. Lek och umgänge kan i större utsträckning kräva planering och vuxenskjuts.</p><h3>Vad händer i vardagen?</h3><p>Kompisar kan hamna på olika turer eller i olika skolor. Föräldrar som tidigare möttes vid den lokala skolan kan få färre kontakter. Det kan göra både barnens umgänge och den praktiska hjälpen mellan familjer svårare.</p><p>Fallstudien från Ballum beskriver förlust av lokalt socialt kapital efter en skolstängning. Den motiverar att kommunen också undersöker nätverken runt barnen, inte enbart skolans organisation.</p>${source(NETWORKS,'Fallstudie · lokala nätverk efter skolstängning')}<h3>En konkret kartläggning behövs</h3><ul class="detail-list"><li>Vilka kompisgrupper som kan splittras av nya placeringar och busstider.</li><li>Hur barn kan träffa vänner och delta lokalt utan att alltid bli skjutsade.</li><li>Hur barnens egna erfarenheter och synpunkter tas in före och efter förändringen.</li></ul>${source(PDF+'#page=8','Kommunens avgränsning av samhällseffekter · PDF-sida 8')}<p class="note">Den lokala omfattningen är inte kartlagd. Studien gäller en annan plats och bevisar inte att varje nätverk i Tidaholm bryts.</p>`;
 if(id==='alternatives')return `<h2>Jämför alternativen innan beslutet</h2><p>Kommunens egna skoldialoger visar att invånare har föreslagit flera andra vägar: ändrade upptagningsområden, att personal och stöd flyttas mer i stället för barnen, löpande underhåll, renovering och att landsbygdsskolorna används som en tillgång för inflyttning.</p>${source(DIALOGS,'Tidaholms kommun · sammanställning av skoldialogerna')}<h3>Alternativ som behöver få samma granskning</h3><ul class="detail-list"><li>Anpassa upptagningsområden så att befintlig kapacitet används på ett annat sätt.</li><li>Flytta specialister, resurser eller delar av personalen mellan skolor i stället för att flytta alla barn.</li><li>Renovera och underhålla stegvis, med redovisad kostnad per år.</li><li>Pröva gemensam ledning, delade tjänster och andra samarbetsformer mellan mindre enheter.</li><li>Jämför en etappvis lösning med att stänga tre skolor och två förskolor samtidigt.</li></ul><h3>En öppen jämförelsetabell behövs</h3><table class="mini-table"><tr><th>Varje alternativ ska visa</th><th>Frågan som ska besvaras</th></tr><tr><td>Ekonomi</td><td>Investering, drift, skolskjuts och verklig nettobesparing</td></tr><tr><td>Barnens vardag</td><td>Restid, grupper, bemanning, stöd, trygghet och fritid</td></tr><tr><td>Hela kommunen</td><td>Inflyttning, bostäder, jobb, landsbygd och trafik</td></tr><tr><td>Risk</td><td>Vad händer om elevprognos, kostnad eller utflyttning blir annorlunda?</td></tr></table><p>Barnkonventionen kräver att barnets bästa beaktas i beslut som rör barn och att barn får komma till tals. Skollagen kräver att utbildningen vilar på vetenskaplig grund och beprövad erfarenhet. Det betyder inte att lagen i sig väljer skolstruktur, men kommunen behöver visa hur barnets bästa och kunskapsläget faktiskt har vägts in.</p>${source(CHILD_CONVENTION,'Barnkonventionen som svensk lag · artiklarna 3 och 12')}${source(SCHOOL_LAW,'Skollagen · vetenskaplig grund och beprövad erfarenhet')}<p>Forskning från Sverige och Danmark visar att en nedläggning kan påverka familjers vardag, lokala nätverk och elevers resultat. Det bevisar inte att varje nedläggning är fel, men det höjer kravet på att alternativen jämförs öppet.</p>${source(VILLAGE_SCHOOL,'Cedering & Wihlborg 2020 · svensk originalstudie')}${source(DENMARK_RESULTS,'Beuchert m.fl. · dansk originalstudie')}<p class="note">Listan är en granskningsram, inte ett påstående om att alla alternativ är billigare eller bättre. Kommunen behöver visa vilka som utretts, med vilka siffror och varför de valts bort.</p>${source(PDF+'#page=8','Kommunens utredning och dess avgränsningar · PDF-sida 8')}`;
 if(id==='total')return `<h2>Vad betyder bruttosumman?</h2><div class="detail-value" data-live="selectedGross">${nf(r.selectedGross)} mkr</div><table class="mini-table" id="total-table"></table><p>En räkneöversikt för olika berörda aktörer: bostadsägarnas tillgångsvärde, hushållens extra bilkostnader och kommunens egna bruttoskatteintäkter.</p><p><b>Detta är inte en kommunal eller samhällsekonomisk nettokostnad.</b> Besparingar, utjämning, förändrade verksamhetskostnader, framtida bostadsköpares position och vinster i andra kommuner är inte avräknade. Tidsåtgången ingår inte.</p><p class="note">Värdefallet räknas en gång. Bilkostnaden antas återkomma hos kvarvarande hushåll. Skattebortfallet ökar successivt enligt utflyttningsantagandet. Beloppen har varken inflation eller diskontering.</p>${fields(['years','ramp'])}${source(EQUALIZATION,'Kommunalekonomisk utjämning · SCB')}`;
 if(id==='settings')return `<h2>Ändra antagandena</h2><p>Resultaten uppdateras direkt. Inga tomma startvärden behövs.</p>${section('Bostadsvärden',['drop','homes_fro','price_fro','homes_val','price_val','homes_eke','price_eke'])}${section('Extra förskoleresor',['drivingHouseholds','kmPerDay','drivingDays','litersPerMil','fuelPrice','otherCostPerKm','adultMinutes'])}${section('Elevernas restid',['pupilMinutes','schoolDays'])}${section('Pendling · uppskattade hushåll',['childPerHousehold','commuteShare_val','commuteShare_fro','commuteShare_eke'])}${section('Skolskjuts · separat räkneexempel',['busKmPerDay','busDays','busCostPerKm','transportOffsets'])}${section('Utflyttning och skatteintäkter',['departures','newHouseholds','ramp','years','taxpayers','taxableIncome','taxRate'])}<p class="note">20 % och 50 hushåll är riskantaganden. 395 bostäder är ett elevbaserat estimat. Bruttosumman är inte ett nettoresultat.</p><div class="mini-actions"><button class="edit-button" data-action="reset">Återställ startscenariot</button><button class="text-button" data-action="copy-scenario">Kopiera kalkylen ↗</button></div>`;
 if(id==='sources')return `<h2>Källor och beräkningssätt</h2><p><b>Dokumenterade uppgifter:</b> antal barn ht 2026, kostnad per elev 2025 och utredningens avgränsningar. Forskningen och myndighetsstödet om lärmiljön länkas separat.</p><p><b>Scenarioantaganden:</b> prisfall, bostadsantal, snittvärden, utflyttning, körsträckor, tidsåtgång och inkomster.</p>${source(PDF,'Tidaholms skolstrukturutredning · 80 PDF-sidor')}${source(BUDGET,'Strategisk plan och budget 2026–2028')}${source(DIALOGS,'Tidaholms kommun · skoldialogerna och invånarnas alternativ')}${source(EQUALIZATION,'Kommunalekonomisk utjämning · SCB')}${source(IFAU,'IFAU · mindre klasser och långsiktiga resultat')}${source(SCHOOL_SIZE_REVIEW,'Leithwood & Jantzi · skolstorlek')}${source(CLASS_INQUIRY,'Regeringen · klasstorlek och lärartäthet')}${source(RELATIONS,'Skolverket · relationer och trygg lärmiljö')}${source(ENVIRONMENT,'SPSM · tillgänglig fysisk lärmiljö')}${source(COMMUTING+'#page=18','Pendling · kommunnivå 2022')}${source(DENMARK,'Tønder · befolkningsutveckling 2021')}${source(DENMARK_RESULTS,'Beuchert m.fl. · elevresultat efter danska skolnedläggningar')}${source(VILLAGE_SCHOOL,'Cedering & Wihlborg · svenska landsbygdsskolor')}${source(IOWA,'Cedar Falls · bostadsvärden 2017')}${source(NETWORKS,'Ballum · lokala nätverk 2018')}${source(FINLAND,'Finland · skolnedläggningar 2021')}${source(CHILD_CONVENTION,'Barnkonventionen som svensk lag')}${source(SCHOOL_LAW,'Skollagen')}${source(SCHOOL_TRAFFIC,'Trafikverket · trafikproblem runt skolor')}${source(SAFE_ROUTES,'Trafikverket · trafiksäkra skolresor')}${source(MOVEMENT,'Folkhälsomyndigheten · barns rörelse')}${source(CHILD_SLEEP,'1177 · barn och sömn')}<p><b>Nya räkneexempel:</b> pendling antar 40 % per skolområde; skolskjuts antar 120 extra buss-km/dag, 180 dagar, 45 kr/km och 500 000 kr i avdrag. Dessa är valda scenarier, inte uppmätta tal. De ingår inte som extra kostnader i bruttosumman. Vägslitage har inte prissatts.</p><div class="field-section"><h3>Bostadsestimatet</h3><p>Per skolområde: elevantal ÷ 1,6 elever per hushåll ÷ 40 %, avrundat uppåt. Det ger 74, 152 och 169 uppskattade bostäder. De två faktorerna är modellantaganden, inte lokal statistik. Förskolebarn läggs inte till i bostadsmodellen, vilket undviker syskondubbelräkning men också kan missa hushåll utan skolelever.</p></div><div class="field-section"><h3>Prisfall och utflyttning</h3><p>20 % prisfall och 50 utflyttade hushåll kommer från användarens riskbedömning. De är inte forskningsresultat eller fastställda prognoser. Noll tillkommande hushåll är också ett scenarioantagande.</p></div><div class="field-section"><h3>Förskoleresor och skattebortfall</h3><p>35 kvarvarande resehushåll uppskattas från 25 + 19 barn med 1,3 förskolebarn per hushåll. Körning, drivmedelspris och bilkostnad är schabloner. Skatteberäkningen använder beskattningsbar inkomst; utjämning och förändrade offentliga kostnader beräknas inte.</p></div><p class="note">Underlag till och med 14 oktober 2026. Förslaget är inte ett slutligt beslut. Beräkningarna illustrerar risker som kommunen behöver bedöma.</p>`;
 return '<h2>Uppgiften saknas</h2>';
}
function panelHTML(id){const body=panelBodyHTML(id),pointId=id==='jobs'?'rural':id;if(!points.some(p=>p.id===pointId))return body;const q=question(pointId),official=body.includes('municipal-source')?'':source(PDF,'Tidaholms kommuns officiella skolstrukturutredning');return q+body.replace(q,'')+official;}
function updatePanelFigures(){if(!activePanel)return;const r=result;const values={drop:state.drop+' %',housing:nf(r.housing)+' mkr',driving:nf(r.driving/1e6,2)+' mkr/år',adultHours:integer(r.adultHours)+' timmar/år',pupilHours:integer(r.pupilHours)+' timmar/år',grossTax:nf(r.grossTax/1e6,2)+' mkr/år',selectedGross:nf(r.selectedGross)+' mkr',busKm:integer(r.busKm)+' buss-km/år'};document.querySelectorAll('[data-live]').forEach(el=>el.textContent=values[el.dataset.live]);const commuters=document.getElementById('commute-table');if(commuters)commuters.innerHTML=commuteTable();const bus=document.getElementById('bus-formula');if(bus)bus.innerHTML='Extra trafik: '+integer(r.busKm)+' km/år.<br>Antagen merkostnad: '+integer(r.busGross)+' kr/år.<br>Antagna motposter: '+integer(state.transportOffsets)+' kr/år.<br><b>Skillnad: '+integer(r.busNet)+' kr/år.</b><br>För ±0 krävs motposter på '+integer(r.busGross)+' kr/år vid dessa antaganden.';const traffic=document.getElementById('traffic-formula');if(traffic)traffic.innerHTML='Bussar: '+integer(r.busKm)+' extra km/år i scenariot.<br>Kvarvarande förskolefamiljers bilar: '+integer(r.km)+' extra km/år i scenariot.<br>Visas separat eftersom vägslitage och resvägar skiljer sig.';const table=document.getElementById('housing-table');if(table)table.innerHTML=housingTable();const drive=document.getElementById('driving-formula');if(drive)drive.innerHTML='Extra körning: '+integer(r.km)+' km/år.<br>Drivmedel: '+integer(r.fuel)+' kr/år.<br>Övrig rörlig bilkostnad: '+integer(r.otherCar)+' kr/år.<br>Summa: '+integer(r.driving)+' kr/år.';const migration=document.getElementById('migration-formula');if(migration)migration.innerHTML='Full effekt: '+integer(r.netDepartures)+' hushåll × '+state.taxpayers+' skattebetalare × '+integer(state.taxableIncome)+' kr × '+nf(state.taxRate,2)+' % = '+nf(r.grossTax/1e6,2)+' mkr/år.<br>Successivt över '+state.years+' år: '+nf(r.cumulativeTax/1e6,2)+' mkr brutto.';const total=document.getElementById('total-table');if(total)total.innerHTML='<tr><td>Bostadsvärden · en gång</td><td>'+nf(r.housing)+' mkr</td></tr><tr><td>Extra bilkostnad · '+state.years+' år</td><td>'+nf(r.cumulativeDriving/1e6,2)+' mkr</td></tr><tr><td>Bruttoskatt · successivt över '+state.years+' år</td><td>'+nf(r.cumulativeTax/1e6,2)+' mkr</td></tr><tr><td>Summa valda bruttobelopp</td><td>'+nf(r.selectedGross)+' mkr</td></tr>';}
const dialog=document.getElementById('detail-dialog');
function openPanel(id){activePanel=id;lastFocus=document.activeElement;document.getElementById('dialog-eyebrow').textContent=id==='settings'?'REDIGERA SCENARIOT':points.find(p=>p.id===id)?.type==='forskning'?'FORSKNING OCH FRÅGOR':points.find(p=>p.id===id)?.type==='fråga'?'FRÅGA OCH UNDERLAG':points.find(p=>p.id===id)?.type==='fakta'?'DOKUMENTERAD UPPGIFT':'KALKYL OCH FÖRDJUPNING';document.getElementById('dialog-content').innerHTML=panelHTML(id);updatePanelFigures();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.getElementById('close-dialog').focus();}
function closePanel(){dialog.close();activePanel=null;(lastFocus?.isConnected?lastFocus:document.querySelector('#point-grid .point')).focus();}
document.getElementById('close-dialog').addEventListener('click',closePanel);
dialog.addEventListener('cancel',event=>{event.preventDefault();closePanel();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closePanel();}});
document.addEventListener('click',event=>{const open=event.target.closest('[data-open]');if(open){openPanel(open.dataset.open);return;}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='reset'){state={...DEFAULTS};renderDashboard();if(activePanel)openPanel(activePanel);}if(action==='estimate'){areas.forEach(a=>state['homes_'+a.key]=estimateHomes(a.pupils,state.childPerHousehold,state.familyShare));renderDashboard();openPanel('housing');notify('Bostadsantalet har räknats om från elevmodellen.');}if(action==='copy-scenario')copyText(scenarioText());});
document.addEventListener('input',event=>{const el=event.target;if(!el.dataset.setting)return;const errors=dialog.querySelectorAll('.field-error,#field-error');if(el.value===''||!el.validity.valid){errors.forEach(e=>e.textContent='Ange ett giltigt värde. Kalkylen använder senaste giltiga värdet tills fältet är rättat.');return;}errors.forEach(e=>e.textContent='');state[el.dataset.setting]=Number(el.value);renderDashboard();});
let timer;function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function copyText(value){try{await navigator.clipboard.writeText(value);notify('Kopierat.');}catch{const el=document.createElement('textarea');el.value=value;document.body.appendChild(el);el.select();const ok=document.execCommand('copy');el.remove();notify(ok?'Kopierat.':'Kopiering stöds inte i denna webbläsare.');}}
function scenarioText(){return 'Tidaholm — scenario, inte prognos\n'+Object.entries(state).map(([key,value])=>(configs[key]?.label||key)+': '+value).join('\n')+'\n\nBostadsvärdefall: '+nf(result.housing)+' mkr (engångseffekt)\nExtra bilkostnad: '+nf(result.driving/1e6,2)+' mkr/år\nMinskade egna skatteintäkter vid full effekt: '+nf(result.grossTax/1e6,2)+' mkr/år brutto\nValda bruttobelopp över '+state.years+' år: '+nf(result.selectedGross)+' mkr\nEj kommunal eller samhällsekonomisk nettokostnad. Utjämning, statsbidrag och offentliga kostnadsförändringar ingår inte.\nSeparat skolskjutsexempel: '+integer(result.busKm)+' extra km/år; merkostnad '+integer(result.busGross)+' kr; antagna avdrag '+integer(state.transportOffsets)+' kr; netto '+integer(result.busNet)+' kr/år. Ingår inte i bruttosumman.\nUppskattade pendlande skolfamiljer till angivna arbetsorter: '+integer(result.commuteTotal)+' hushåll; scenario, inte kartläggning.\nKälla för barnantal: '+PDF;}
const copyQuestions=()=>copyText('21 frågor om skolstrukturförslaget i Tidaholm\n\n'+points.map((p,i)=>(i+1)+'. '+p.question).join('\n\n'));document.getElementById('copy-questions').addEventListener('click',copyQuestions);document.getElementById('copy-questions-top').addEventListener('click',copyQuestions);
document.getElementById('print').addEventListener('click',()=>window.print());
renderDashboard();
